import os
import tomllib
from typing import Dict, Any, Optional


class ConfigError(Exception):
    """Exception raised for configuration errors."""
    def __init__(self, key_path: str, expected: str, actual: str):
        self.key_path = key_path
        self.expected = expected
        self.actual = actual
        super().__init__(f"Config error at '{key_path}': expected {expected}, got '{actual}'")


def int_coerce(value: str) -> int:
    """Coerce string to integer."""
    try:
        return int(value)
    except ValueError:
        raise ConfigError("", "integer", value)


def float_coerce(value: str) -> float:
    """Coerce string to float."""
    try:
        return float(value)
    except ValueError:
        raise ConfigError("", "float", value)


def bool_coerce(value: str) -> bool:
    """Coerce string to boolean."""
    true_values = {'true', '1', 'yes', 'True'}
    false_values = {'false', '0', 'no', 'False'}
    value_lower = value.lower()
    if value_lower in true_values:
        return True
    elif value_lower in false_values:
        return False
    else:
        raise ConfigError("", "boolean", value)


def str_coerce(value: str) -> str:
    """Coerce string to string (no-op)."""
    return value


def load_toml(toml_path: Optional[str]) -> Dict[str, Any]:
    """Load TOML file if it exists."""
    if not toml_path:
        return {}
    try:
        with open(toml_path, 'rb') as f:
            return tomllib.load(f)
    except FileNotFoundError:
        return {}
    except Exception as e:
        raise ConfigError("TOML parsing", "valid TOML", str(e))


